/* ---------------------------------------------------------------- motion
   Mode-independent: motion does not change between light and dark.

   Calibrated for interface work, not for demos. A micro-interaction at 300ms
   reads as sluggish; 150ms reads as responsive. Exits are shorter than
   entrances because a thing leaving has already been decided on. Every value
   below is one an existing WunderUI component was already using — the tokens
   consolidate the scale, they do not re-time the library. */
/* A nested .light or .dark section re-resolves --surface against its own
   background — declared only on :root it would keep the page's colour, and a
   dark card on a light page would ring its avatars in white. */
.light,
.dark {
  --surface: var(--background);
}

:root {
  /* The colour of whatever an element sits on. Containers override it with
     their own fill (cards, popovers, dialogs, sheets), so a ring or cut-out
     can match its surroundings instead of the page. */
  --surface: var(--background);

  --duration-instant: 80ms;      /* tooltip dismiss, press release */
  --duration-fast: 150ms;        /* the default exit; hover, focus, checkbox */
  --duration-base: 250ms;        /* dropdown, popover, tab, backdrop, collapse */
  --duration-slow: 350ms;        /* dialog, toast, switch — a surface arriving */
  --duration-deliberate: 450ms;  /* sheet, full-width panel, orchestrated beats */
  --duration-ambient: 700ms;     /* progress and meter fills — data, not chrome */
  --duration-loop: 1800ms;       /* one cycle of an endless ambient loop (skeleton shimmer, pulse) — never a transition */

  /* Travel distances. Restraint is the point: a menu that slides 20px looks
     like it fell in. Anything anchored to a trigger barely moves at all. */
  --travel-xs: 2px;   /* tooltip — stays glued to its anchor */
  --travel-sm: 4px;   /* popover, dropdown, context menu */
  --travel-md: 8px;   /* dialog, toast, inline panel */
  --travel-lg: 16px;  /* section reveal on scroll */

  --scale-press: 0.97;   /* pressed button */
  --scale-enter: 0.96;   /* dialog arriving */
}

/* ---------------------------------------------------------------- density
   Every size that sets how dense the components are lives here, once.
   Components read these tokens (`h-(--control-md)`, `py-(--row-py)` …); page
   layout — the consumer's own paddings, gaps and widths — never does, so a
   density change resizes controls, rows and surfaces but not the page grid.

   Compact (default since Oct 2026): one scale for buttons and fields,
   sm 32 · md 36 · lg 40 · xl 44 · 2xl 48.
   Comfortable (the sizes before Oct 2026, Figma 1:1): set
   `data-density="comfortable"` on <html> or any wrapper; `data-density="compact"`
   switches a subtree back. To make comfortable the default again, move
   `:root,` from the first selector list to the second — nothing else changes.

   Values are plain lengths on purpose: a token built from another token with
   calc() would be computed once at :root and would not follow a nested
   data-density. Components do the arithmetic where they use a token. */
:root,
[data-density="compact"] {
  /* Control heights — Button, Tabs, Segment, Pagination, table head, search
     triggers, Command input. */
  --control-sm: 2rem;      /* 32 */
  --control-md: 2.25rem;   /* 36 */
  --control-lg: 2.5rem;    /* 40 */
  --control-xl: 2.75rem;   /* 44 */
  --control-2xl: 3rem;     /* 48 */
  /* Button inline padding per size (the icon side takes 2 px less, 2xl 4 px). */
  --control-px-sm: 0.75rem;    /* 12 */
  --control-px-md: 0.875rem;   /* 14 */
  --control-px-lg: 1rem;       /* 16 */
  --control-px-xl: 1.125rem;   /* 18 */
  --control-px-2xl: 1.25rem;   /* 20 */
  /* Field heights — Input, InputGroup, NativeSelect, Combobox, Autocomplete,
     TextField. Same steps as the controls, so a field and a button of the
     same size line up. */
  --field-sm: 2rem;        /* 32 */
  --field-md: 2.25rem;     /* 36 */
  --field-lg: 2.5rem;      /* 40 */
  /* Textarea minimum heights. */
  --textarea-sm: 4.5rem;   /* 72 */
  --textarea-md: 6rem;     /* 96 */
  --textarea-lg: 8rem;     /* 128 */
  /* Rows: table cells (row ≈ 33 px with one line of text-sm), list rows,
     menu items (32), sidebar and nav items (36). */
  --row-py: 0.375rem;      /* 6 */
  --list-row-py: 0.5rem;   /* 8 */
  --menu-item-py: 0.375rem; /* 6 */
  --nav-item-py: 0.5rem;   /* 8 */
  /* Surfaces: Card (default size) and Sheet padding. */
  --card-padding: 1rem;    /* 16 */
}
[data-density="comfortable"] {
  --control-sm: 2.25rem;   /* 36 */
  --control-md: 2.5rem;    /* 40 */
  --control-lg: 2.75rem;   /* 44 */
  --control-xl: 3rem;      /* 48 */
  --control-2xl: 3.5rem;   /* 56 */
  --control-px-sm: 0.875rem;   /* 14 */
  --control-px-md: 1rem;       /* 16 */
  --control-px-lg: 1.125rem;   /* 18 */
  --control-px-xl: 1.25rem;    /* 20 */
  --control-px-2xl: 1.5rem;    /* 24 */
  --field-sm: 2.25rem;     /* 36 */
  --field-md: 2.75rem;     /* 44 */
  --field-lg: 3.25rem;     /* 52 */
  --textarea-sm: 5rem;     /* 80 */
  --textarea-md: 7rem;     /* 112 */
  --textarea-lg: 9rem;     /* 144 */
  --row-py: 0.625rem;      /* 10 */
  --list-row-py: 0.75rem;  /* 12 */
  --menu-item-py: 0.5rem;  /* 8 */
  --nav-item-py: 0.625rem; /* 10 */
  --card-padding: 1.25rem; /* 20 */
}

/* Borders default to the theme border colour. Tailwind v4's preflight uses
   currentColor, so without this a plain `border` on a table row, card or
   divider draws in the text colour (black). Utilities still override it. */
@layer base {
  *,
  ::before,
  ::after,
  ::backdrop,
  ::file-selector-button {
    border-color: var(--border);
  }
}

/* Tailwind v4 has no `--duration-*` theme namespace, so the scale is exposed
   as named utilities instead of `duration-[var(--duration-base)]`. Each one
   sets --tw-duration as well, which is what tw-animate-css reads for
   `animate-in` / `animate-out`, so `data-open:duration-base` works. */
@utility duration-instant {
  --tw-duration: var(--duration-instant);
  transition-duration: var(--duration-instant);
  animation-duration: var(--duration-instant);
}
@utility duration-fast {
  --tw-duration: var(--duration-fast);
  transition-duration: var(--duration-fast);
  animation-duration: var(--duration-fast);
}
@utility duration-base {
  --tw-duration: var(--duration-base);
  transition-duration: var(--duration-base);
  animation-duration: var(--duration-base);
}
@utility duration-slow {
  --tw-duration: var(--duration-slow);
  transition-duration: var(--duration-slow);
  animation-duration: var(--duration-slow);
}
@utility duration-deliberate {
  --tw-duration: var(--duration-deliberate);
  transition-duration: var(--duration-deliberate);
  animation-duration: var(--duration-deliberate);
}
@utility duration-ambient {
  --tw-duration: var(--duration-ambient);
  transition-duration: var(--duration-ambient);
  animation-duration: var(--duration-ambient);
}

/* `delay-instant` is the `--duration-instant` step used as a delay (the
   tooltip's hover intent). It also sets --tw-animation-delay, which
   tw-animate-css reads for `animate-in`, so `data-open:delay-instant` works. */
@utility delay-instant {
  --tw-animation-delay: var(--duration-instant);
  transition-delay: var(--duration-instant);
  animation-delay: var(--duration-instant);
}

/* The looping sweep shared by Skeleton and ChartSkeleton, used on their
   ::before as `before:animate-shimmer`. */
@utility animate-shimmer {
  animation: wunderui-shimmer var(--duration-loop) var(--ease-move) infinite;
}

@keyframes wunderui-copied-ring {
  0% { box-shadow: 0 0 0 0 color-mix(in oklab, var(--success) 60%, transparent); }
  100% { box-shadow: 0 0 0 8px transparent; }
}

@keyframes wunderui-shimmer {
  100% { translate: 100% 0; }
}

@keyframes wunderui-text-shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

/* Logo loader: the three strokes of the mark drift apart and click back in.
   Offsets come from --logo-dx/--logo-dy (travel tokens, set per stroke);
   the small pass through centre at 26% is the settle. Timing per segment is
   the element's --ease-move; the segments approximate deliberate (gather),
   slow (hold), slow (release), base (rest) of one --logo-cycle. */
@keyframes wunderui-logo-assemble {
  0%, 100% { translate: var(--logo-dx, 0px) var(--logo-dy, 0px); }
  26% { translate: calc(var(--logo-dx, 0px) * -0.2) calc(var(--logo-dy, 0px) * -0.2); }
  34%, 60% { translate: 0 0; }
  84% { translate: var(--logo-dx, 0px) var(--logo-dy, 0px); }
}

/* Chart appear (useInViewAppear in chart.tsx): Line, Area and Candlestick
   charts and Sparkline wait until a quarter of them is on screen, then the
   box fades and rises in while the series arrive — lines draw left to right
   (recharts, or the stroke-dashoffset below for Sparkline), area fills fade
   and rise in just after, candles and volume bars grow from their baseline
   with a short stagger (--chart-stagger 0…1, set per candle). The attribute
   is "hidden" before, "in" for the sequence, then "done"/"static" — the
   animations only exist while it is "in", so later re-renders, resizes and
   tooltips never replay them. Transforms only: nothing shifts the layout. */
[data-chart-appear="hidden"] {
  opacity: 0;
  transform: translateY(var(--travel-md));
}
[data-chart-appear="in"] {
  animation: wunderui-chart-rise var(--duration-slow) var(--ease-entrance) both;
  /* inside a dashboard load sequence: when the chart's card has landed */
  animation-delay: var(--load-content-delay, 0ms);
}
/* Area fills are not faded here: recharts already reveals them left to right with
   the line, and swaps the path element when its animation ends — a CSS fade on it
   would restart then and make the fill blink (Oct 8 2026). */
[data-chart-appear="in"] [data-chart-fade] {
  animation: wunderui-chart-fade var(--duration-deliberate) var(--ease-entrance) var(--duration-base) both;
}
[data-chart-appear="in"] [data-chart-grow] {
  transform-box: fill-box;
  transform-origin: 50% 100%;
  animation: wunderui-chart-grow var(--duration-slow) var(--ease-entrance) both;
  animation-delay: calc(var(--chart-stagger, 0) * var(--duration-base));
}
[data-chart-appear="in"] [data-chart-draw] {
  stroke-dasharray: 1;
  animation: wunderui-chart-draw var(--duration-ambient) var(--ease-entrance) both;
}
@keyframes wunderui-chart-rise {
  from { opacity: 0; transform: translateY(var(--travel-md)); }
}
@keyframes wunderui-chart-fade {
  from { opacity: 0; transform: translateY(var(--travel-sm)); }
}
@keyframes wunderui-chart-grow {
  from { transform: scaleY(0); }
}
@keyframes wunderui-chart-draw {
  from { stroke-dashoffset: 1; }
  to { stroke-dashoffset: 0; }
}

/* Chart system v2 (@wunderui/react/charts): the enter sequence. The marks
   layer carries data-chart-enter and is remounted on first view, after
   loading, on new data (period switch) and on reload, so it plays every time
   the data arrives. Lines draw along their path, dashed lines and areas wipe
   in left to right (clip-path, M21), bars grow from the zero line, labels
   and markers fade in at the end; series and bars are staggered by
   --enter-i. A draw is a movement along the data, so it runs on
   --ease-move over two ambient steps (1.4 s, like the reveal of bklit and
   evilcharts) — slower than chrome on purpose. Opt-in motion only (M7). */
[data-chart-enter] {
  --chart-enter: calc(var(--duration-ambient) * 2);
}
/* Bullet charts (owner, Oct 22 2026): the measure is a brand-600 fill in light
   (3.86:1 against the grey-200 band, 4.35:1 against the 55 % band, 4.99:1 against
   the card), brand-300 in dark (5.64:1 against the dark band). The target is a
   foreground bar with a 2 px card-coloured halo: light 4.21:1 against the
   measure and ≥ 16:1 against the bands; dark the halo keeps it apart from the
   light measure (white on the card halo 16.85:1). */
:root {
  --chart-bullet-target: var(--foreground);
  --chart-bullet-measure: var(--brand-600);
  --chart-bullet-band: var(--alternative-200);
}
.dark {
  --chart-bullet-measure: var(--brand-300);
  --chart-bullet-band: var(--alternative-800);
}
/* Waterfall (owner, Oct 22 2026): one indigo scale instead of green / red.
   Totals the strongest step, increases a medium step, decreases a light
   fill with a 1 px edge in the medium step — the edge carries the 3:1
   against the card; the +/− sign in labels and tooltip carries the meaning
   too. Dark: the same roles mirrored (strongest = lightest on the dark card). */
:root {
  --chart-waterfall-total: var(--brand-700);
  --chart-waterfall-increase: var(--brand-500);
  --chart-waterfall-decrease: var(--brand-300);
  --chart-waterfall-edge: var(--brand-500);
}
.dark {
  --chart-waterfall-total: var(--brand-300);
  --chart-waterfall-increase: var(--brand-500);
  --chart-waterfall-decrease: var(--brand-700);
  --chart-waterfall-edge: var(--brand-500);
}
/* Hover colour of a series (owner, Oct 22 2026): two steps lighter on its
   own scale; hoverColor() in charts/chart-utils.ts maps a series colour here.
   Dark: also two steps lighter than the dark series colour, away from the
   dark card, so the hovered mark keeps (and gains) contrast. */
:root {
  --chart-hover-indigo: var(--brand-400);
  --chart-hover-blue: var(--blue-400);
  --chart-hover-purple: var(--purple-400);
  --chart-hover-green: var(--green-400);
  --chart-hover-grey: var(--dark-100);
  --chart-hover-orange: var(--orange-400);
  --chart-hover-pink: var(--pink-400);
  --chart-hover-yellow: var(--yellow-400);
}
.dark {
  --chart-hover-indigo: var(--brand-400);
  --chart-hover-blue: var(--blue-300);
  --chart-hover-purple: var(--purple-300);
  --chart-hover-green: var(--green-300);
  --chart-hover-grey: var(--dark-200);
  --chart-hover-orange: var(--orange-400);
  --chart-hover-pink: var(--pink-400);
  --chart-hover-yellow: var(--yellow-400);
}
/* Lines, points and thin strokes of a series (owner, Oct 22 2026): 3:1 against
   the card (WCAG 1.4.11). In light the blue, purple, green, grey, pink and
   yellow fill steps fall short, so their lines take a darker step; fills,
   areas and bars keep the fill step. lineColor() in charts/chart-utils.ts
   maps a series colour to these. Dark: the fill colours again. */
:root {
  --chart-line-blue: var(--blue-700);
  --chart-line-purple: var(--purple-700);
  --chart-line-green: var(--green-800);
  --chart-line-grey: var(--dark-400);
  --chart-line-pink: var(--pink-700);
  --chart-line-yellow: var(--yellow-800);
}
.dark {
  --chart-line-blue: var(--chart-2);
  --chart-line-purple: var(--chart-3);
  --chart-line-green: var(--chart-4);
  --chart-line-grey: var(--chart-5);
  --chart-line-pink: var(--pink-600);
  --chart-line-yellow: var(--yellow-600);
}
/* Text on chart fills (generated by the chart system, Oct 21 2026): for each
   series colour and fill opacity (100 … 25 %) the text token — white or
   near-black — with the higher contrast over the card. labelOn() in
   charts/chart-utils.ts picks the variable. Every pair is ≥ 4.5:1 at these steps
   (lowest 4.59:1, chart-4 at 55 % in dark). */
:root {
  --chart-on-chart-1-100: var(--light-100);
  --chart-on-chart-1-85: var(--dark-1000);
  --chart-on-chart-1-70: var(--dark-1000);
  --chart-on-chart-1-55: var(--dark-1000);
  --chart-on-chart-1-40: var(--dark-1000);
  --chart-on-chart-1-25: var(--dark-1000);
  --chart-on-chart-2-100: var(--dark-1000);
  --chart-on-chart-2-85: var(--dark-1000);
  --chart-on-chart-2-70: var(--dark-1000);
  --chart-on-chart-2-55: var(--dark-1000);
  --chart-on-chart-2-40: var(--dark-1000);
  --chart-on-chart-2-25: var(--dark-1000);
  --chart-on-chart-3-100: var(--dark-1000);
  --chart-on-chart-3-85: var(--dark-1000);
  --chart-on-chart-3-70: var(--dark-1000);
  --chart-on-chart-3-55: var(--dark-1000);
  --chart-on-chart-3-40: var(--dark-1000);
  --chart-on-chart-3-25: var(--dark-1000);
  --chart-on-chart-4-100: var(--dark-1000);
  --chart-on-chart-4-85: var(--dark-1000);
  --chart-on-chart-4-70: var(--dark-1000);
  --chart-on-chart-4-55: var(--dark-1000);
  --chart-on-chart-4-40: var(--dark-1000);
  --chart-on-chart-4-25: var(--dark-1000);
  --chart-on-chart-5-100: var(--dark-1000);
  --chart-on-chart-5-85: var(--dark-1000);
  --chart-on-chart-5-70: var(--dark-1000);
  --chart-on-chart-5-55: var(--dark-1000);
  --chart-on-chart-5-40: var(--dark-1000);
  --chart-on-chart-5-25: var(--dark-1000);
