@media (prefers-reduced-motion: no-preference) {
  [data-chart-enter] [data-enter="draw"] {
    stroke-dasharray: 1;
    animation: wunderui-chart-enter-draw var(--chart-enter) var(--ease-move) both;
    animation-delay: calc(var(--load-content-delay, 0ms) + var(--enter-i, 0) * var(--duration-base));
  }
  [data-chart-enter] [data-enter="wipe"] {
    animation: wunderui-chart-enter-wipe var(--chart-enter) var(--ease-move) both;
    animation-delay: calc(var(--load-content-delay, 0ms) + var(--enter-i, 0) * var(--duration-base));
  }
  [data-chart-enter] [data-enter="fade"] {
    animation: wunderui-chart-enter-fade var(--duration-slow) var(--ease-entrance) both;
    animation-delay: calc(var(--load-content-delay, 0ms) + var(--chart-enter) * 0.7 + var(--enter-i, 0) * var(--duration-base));
  }
  [data-chart-enter] [data-enter^="grow"] {
    transform-box: fill-box;
    transform-origin: 50% 100%;
    animation: wunderui-chart-enter-grow calc(var(--chart-enter) * 0.75) var(--ease-entrance) both;
    animation-delay: calc(var(--load-content-delay, 0ms) + var(--enter-i, 0) * var(--duration-deliberate));
  }
  [data-chart-enter] [data-enter="grow-down"] {
    transform-origin: 50% 0%;
  }
  /* candles open up from their middle */
  [data-chart-enter] [data-enter="grow-mid"] {
    transform-origin: 50% 50%;
  }
  /* scatter dots scale up from their centre */
  [data-chart-enter] [data-enter="dot"] {
    transform-box: fill-box;
    transform-origin: 50% 50%;
    animation: wunderui-chart-enter-dot var(--duration-slow) var(--ease-overshoot) both;
    animation-delay: calc(var(--load-content-delay, 0ms) + var(--enter-i, 0) * var(--duration-base));
  }
  [data-chart-enter] [data-enter="grow-x"],
  [data-chart-enter] [data-enter="grow-x-rev"] {
    transform-origin: 0% 50%;
    animation-name: wunderui-chart-enter-grow-x;
  }
  [data-chart-enter] [data-enter="grow-x-rev"] {
    transform-origin: 100% 50%;
  }
  /* radial charts: wedges unfold from the centre (origin set inline to the
     chart's centre), rings are drawn with the draw rule above */
  [data-chart-enter] [data-enter="pop"] {
    transform-box: view-box;
    animation: wunderui-chart-enter-pop var(--duration-ambient) var(--ease-entrance) both;
    animation-delay: calc(var(--load-content-delay, 0ms) + var(--enter-i, 0) * var(--duration-fast));
  }
}
@media (prefers-reduced-motion: no-preference) {
  /* gauge needle: swings from the start of the scale (--needle-from) to its value */
  [data-chart-enter] [data-enter="needle"] {
    transform-box: view-box;
    /* spring: overshoots a little and settles on the value */
    animation: wunderui-chart-enter-needle calc(var(--duration-ambient) * 2) var(--ease-overshoot) both;
    animation-delay: var(--load-content-delay, 0ms);
  }
}
@keyframes wunderui-chart-enter-dot {
  from { opacity: 0; transform: scale(0); }
}
@keyframes wunderui-chart-enter-needle {
  from { transform: rotate(var(--needle-from, -90deg)); }
}
@keyframes wunderui-chart-enter-pop {
  from { opacity: 0; transform: scale(0.6) rotate(-12deg); }
}
@keyframes wunderui-chart-enter-draw {
  from { stroke-dashoffset: 1; }
  to { stroke-dashoffset: 0; }
}
@keyframes wunderui-chart-enter-wipe {
  from { clip-path: inset(-24px 100% -24px -24px); }
  to { clip-path: inset(-24px -24px -24px -24px); }
}
@keyframes wunderui-chart-enter-fade {
  from { opacity: 0; }
}
@keyframes wunderui-chart-enter-grow {
  from { transform: scaleY(0); }
}
@keyframes wunderui-chart-enter-grow-x {
  from { transform: scaleX(0); }
}

/* Dashboard load sequence (load-sequence.tsx, owner Oct 22 2026). The root
   carries data-load="pending" → ["loading" →] "play" → "done", its page area
   data-load-main. The shell stays visible the whole time; only the page's
   content waits. Nothing flies in: a card (data-load-item) just appears in
   place at its --load-delay — opacity only, --duration-fast — top to bottom
   in reading order, the page built within about half a second. What is inside
   starts at --load-content-delay, once its card is there: charts (the enter
   sequence above), fills (data-load-fill, grow from the start edge, 60 ms
   apart) and NumberRoll digits (60 ms apart, one full turn plus their value,
   a 2 px blur only while they move, --duration-ambient + --duration-base).
   While "loading" (data later than LOAD_SKELETON_DELAY) the content stays
   hidden under its skeletons (data-load-skeleton), which fade out at their
   card's --load-delay when it plays. Reduced motion: no animation at all —
   nothing is held back while pending, cards and numbers are simply there. */
@media (prefers-reduced-motion: no-preference) {
  [data-load="pending"] [data-load-main] > :not([data-load-layer]) {
    opacity: 0;
  }
}
[data-load="loading"] [data-load-main] > :not([data-load-layer]) {
  opacity: 0;
}
[data-roll-col] {
  position: relative;
  display: inline-block;
  /* clips the rolling strip to one line without moving the baseline (overflow would) */
  clip-path: inset(0 -0.25em);
}
[data-roll-strip] {
  position: relative;
  display: block;
}
[data-roll-above] {
  position: absolute;
  inset-inline: 0;
  bottom: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
}
[data-load-fill] {
  transform-origin: left center;
}
[dir="rtl"] [data-load-fill] {
  transform-origin: right center;
}
@media (prefers-reduced-motion: no-preference) {
  [data-load="play"] [data-load-item] {
    animation: wunderui-load-item var(--duration-fast) var(--ease-entrance) both;
    animation-delay: var(--load-delay, 0ms);
  }
  [data-load="play"] [data-load-skeleton] {
    animation: wunderui-load-skeleton-out var(--duration-fast) var(--ease-exit)
      both;
    animation-delay: var(--load-delay, 0ms);
  }
  [data-load="play"] [data-load-fill] {
    animation: wunderui-load-fill var(--duration-ambient) var(--ease-entrance)
      both;
    animation-delay: calc(
      var(--load-content-delay, 0ms) + var(--load-fill-i, 0) *
        var(--duration-instant) * 0.75
    );
  }
  [data-roll-strip] {
    animation:
      wunderui-roll calc(var(--duration-ambient) + var(--duration-base))
        var(--ease-entrance) both,
      /* sharp while it waits for its turn, blurred only while it moves */
        wunderui-roll-blur calc(var(--duration-ambient) + var(--duration-base))
        var(--ease-entrance) forwards;
    animation-delay: calc(
      var(--load-content-delay, 0ms) + var(--roll-delay, 0ms) +
        var(--roll-i, 0) * var(--duration-instant) * 0.75
    );
  }
}
/* opacity only: a card appears where it is, it never moves */
@keyframes wunderui-load-item {
  from {
    opacity: 0;
  }
}
@keyframes wunderui-load-skeleton-out {
  to {
    opacity: 0;
  }
}
@keyframes wunderui-load-fill {
  from {
    scale: 0 1;
  }
}
@keyframes wunderui-roll {
  from {
    transform: translateY(calc(var(--roll-n, 10) * 100%));
  }
}
@keyframes wunderui-roll-blur {
  from,
  30% {
    filter: blur(2px);
  }
  to {
    filter: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  /* useInViewAppear already skips the sequence; this covers the moment
     before hydration, when the server-rendered box is still "hidden". */
  [data-chart-appear] {
    opacity: 1 !important;
    transform: none !important;
  }
  [data-chart-appear],
  [data-chart-appear] * {
    animation: none !important;
  }
  /* A transition is motion too, and until now only animations were covered.
     This drops the moving properties out of every transition while keeping the
     ones that are not motion, so hover and focus states still feel alive:
     the switch thumb stops sliding, the accordion and collapsible panels stop
     animating their height, and the six disclosure chevrons stop rotating,
     without anyone having to remember a motion-reduce: utility on each one.

     Consumers who want a specific transform transition back can re-declare
     transition-property with !important on that element. Verified by the
     reduced-motion sweep in /scripts — see MOTION-SOURCES.md. */
  *,
  *::before,
  *::after {
    transition-property: color, background-color, border-color, outline-color,
      text-decoration-color, fill, stroke, opacity, box-shadow, filter,
      backdrop-filter !important;
  }

  /* M15: tw-animate-css (every animate-in / animate-out: dropdowns, dialogs,
     popovers, tooltips, sheets, badges) ships no reduced-motion guard. Instead of
     cutting the animation to 0.01ms — which also removed the fade — the movement
     is zeroed: no zoom, no slide, no spin, no blur. The opacity fade stays, so
     things still arrive and leave visibly, just without moving. */
  *,
  *::before,
  *::after {
    --tw-enter-scale: 1 !important;
    --tw-enter-rotate: 0 !important;
    --tw-enter-translate-x: 0 !important;
    --tw-enter-translate-y: 0 !important;
    --tw-enter-blur: 0 !important;
    --tw-exit-scale: 1 !important;
    --tw-exit-rotate: 0 !important;
    --tw-exit-translate-x: 0 !important;
    --tw-exit-translate-y: 0 !important;
    --tw-exit-blur: 0 !important;
  }
  [data-open], [data-closed] {
    animation-delay: 0s !important;
  }
}

/* Touch targets (WCAG 2.5.8 / Apple and Material guidance: 44 px). On touch
   screens every WunderUI control gets an invisible hit area of at least
   44 × 44 px, centred on it — the visible size stays the same, so dense
   toolbars, tables and sidebars keep their layout. In @layer base on purpose:
   `position: relative` must lose to an `absolute` / `fixed` utility on the
   same element (a dialog's close button), and the pseudo-element only exists
   where a component does not draw its own ::after. Controls that already
   extend their hit area (checkbox, switch, radio) are not listed. Tooltip triggers count when they are
   buttons (icon-only toolbar and copy buttons). */
@layer base {
  @media (pointer: coarse) {
    :where([data-slot="button"], [data-slot="icon-button"], [data-slot="tabs-trigger"], [data-slot="toggle"], [data-slot="toggle-button"], [data-slot="segment"] button, button[data-slot="tooltip-trigger"], [data-slot="input-group-addon"] button, [data-hit]) {
      position: relative;
    }
    :where([data-slot="button"], [data-slot="icon-button"], [data-slot="tabs-trigger"], [data-slot="toggle"], [data-slot="toggle-button"], [data-slot="segment"] button, button[data-slot="tooltip-trigger"], [data-slot="input-group-addon"] button, [data-hit])::after {
      content: "";
      position: absolute;
      top: 50%;
      left: 50%;
      width: max(100%, 44px);
      height: max(100%, 44px);
      transform: translate(-50%, -50%);
    }
  }
}

/* Text fields at 16 px on phones and touch screens: Safari on iOS zooms the
   whole page when a field under 16 px gets focus. Unlayered on purpose so it
   outranks `text-sm` on the field; the code-entry cells keep their own size. */
@media (pointer: coarse), (max-width: 639.98px) {
  input:not([type="checkbox"], [type="radio"], [type="range"], [type="color"], [type="file"], [type="button"], [type="submit"], [data-slot="otp-field-input"]),
  select,
  textarea {
    font-size: 16px;
  }
}

/* A chart is not a control. Clicking it moves the focus to one of its SVG layers, and the
   browser draws its default focus ring around that layer (a box around the plot). That ring
   is hidden for a mouse click; a keyboard focus (:focus-visible) keeps its ring. */
.recharts-wrapper:focus:not(:focus-visible),
.recharts-wrapper *:focus:not(:focus-visible) {
  outline: none;
}
